
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_gdme_vt_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_gdme_vt", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([7.944877893002596e+00, 3.781439644120559e+00, 9.725501791511268e-01, -8.632964918171047e-01, -1.983520340472471e+00, -2.561151893378688e+00, -2.717128381937931e+00, -2.551220152667681e+00, -2.177051301084988e+00, -1.760028045410009e+00, -1.428707463723600e+00, -7.963195972110243e-01, -5.260376302442534e-01, -5.034111422178263e-01, -4.128004113358887e-01, -3.447849063052708e-01, -4.798940389404397e-01, -1.381462550244874e+00, -6.754418686864130e+00, -6.170544854851523e+01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


